def simple_tokens(text: str) -> List[str]:
    t = text.lower()
    out = []
    for ch in t:
        if ch.isalnum() or ch in " _-.":
            out.append(ch)
        else:
            out.append(" ")
    return [w for w in "".join(out).split() if w]

def sha1(s: str) -> str:
    return hashlib.sha1(s.encode("utf-8")).hexdigest()

def clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, x))

class CerebrasClient:
    def __init__(self, base: str, api_key: str):
        self.base = base.rstrip("/")
        self.key = api_key

    def chat(self, model: str, messages: List[Dict[str, str]], max_tokens: int, temperature: float = 0.3, extra: Optional[Dict[str, Any]] = None, stream: bool = False) -> Dict[str, Any]:
        url = f"{self.base}/chat/completions"
        headers = {"Authorization": f"Bearer {self.key}", "Content-Type": "application/json"}
        payload = {"model": model, "messages": messages, "temperature": temperature}
        if max_tokens:
            payload["max_completion_tokens"] = max_tokens
        if extra:
            payload.update(extra)
        for attempt in range(5):
            try:
                r = requests.post(url, headers=headers, data=json.dumps(payload), timeout=180, stream=stream)
                if r.status_code == 200:
                    if stream:
                        return {"stream": r.iter_lines()}
                    return r.json()
                time.sleep(2 ** attempt)
            except Exception:
                time.sleep(2 ** attempt)
        raise HTTPException(status_code=502, detail="Cerebras chat error")

