def job_create(topic: str) -> str:
    jid = strong_id()
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO jobs(id,topic,status,created_at,updated_at,progress,report_path,logs) VALUES(?,?,?,?,?,?,?,?)",
                    (jid, topic, "created", now_utc(), now_utc(), 0.0, None, json.dumps([])))
        con.commit()
    return jid

def job_update(jid: str, status: Optional[str] = None, progress: Optional[float] = None, log_line: Optional[str] = None, report_path: Optional[str] = None):
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT logs FROM jobs WHERE id=?", (jid,))
        row = cur.fetchone()
        logs = json.loads(row[0]) if row and row[0] else []
        if log_line:
            logs.append(f"{datetime.datetime.utcnow().isoformat()} {log_line}")
        fields = []
        values = []
        if status is not None:
            fields.append("status=?")
            values.append(status)
        if progress is not None:
            fields.append("progress=?")
            values.append(float(clamp(progress, 0.0, 1.0)))
        if report_path is not None:
            fields.append("report_path=?")
            values.append(report_path)
        fields.append("updated_at=?")
        values.append(now_utc())
        fields.append("logs=?")
        values.append(json.dumps(logs[-500:]))
        q = f"UPDATE jobs SET {', '.join(fields)} WHERE id=?"
        values.append(jid)
        cur.execute(q, tuple(values))
        con.commit()

def job_get(jid: str) -> JobStatus:
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT id,topic,status,progress,updated_at,report_path,logs FROM jobs WHERE id=?", (jid,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Job not found")
    return JobStatus(id=row[0], topic=row[1], status=row[2], progress=row[3], updated_at=row[4], report_path=row[5], logs=json.loads(row[6]) if row[6] else [])

def evidence_add_source(url: str, title: str, snippet: str, domain: str, lang: str) -> str:
    sid = strong_id()
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO sources(id,url,title,snippet,domain,lang,added_at) VALUES(?,?,?,?,?,?,?)",
                    (sid, url, title, snippet, domain, lang, now_utc()))
        con.commit()
    return sid

def evidence_add_claim(source_id: str, claim: str, quote: str, quality: str) -> str:
    cid = strong_id()
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO claims(id,source_id,claim,quote,quality,added_at) VALUES(?,?,?,?,?,?)",
                    (cid, source_id, claim, quote, quality, now_utc()))
        con.commit()
    return cid

def evidence_topk_for_topic(topic: str, k: int) -> List[Tuple[str, str, str]]:
    tokens = set(simple_tokens(topic))
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT id,title,url,snippet FROM sources")
        rows = cur.fetchall()
    scored = []
    for sid, title, url, snippet in rows:
        text = f"{title or ''} {snippet or ''}".lower()
        sc = sum(1 for t in tokens if t in text)
        if sc > 0:
            scored.append((sc, sid, title or url, url))
    scored.sort(key=lambda x: x[0], reverse=True)
    return [(sid, title, url) for _, sid, title, url in scored[:k]]

def section_save(index_no: int, title: str, body: str, citations: List[str]) -> str:
    sec_id = strong_id()
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO sections(id,index_no,title,body,citations,created_at) VALUES(?,?,?,?,?,?)",
                    (sec_id, index_no, title, body, json.dumps(citations), now_utc()))
        con.commit()
    return sec_id

def sections_get_all() -> List[Tuple[int, str, str, List[str]]]:
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT index_no,title,body,citations FROM sections ORDER BY index_no ASC")
        rows = cur.fetchall()
    out = []
    for idx, title, body, cit in rows:
        out.append((idx, title, body, json.loads(cit or "[]")))
    return out

def assemble_report(topic: str) -> str:
    lines = []
    lines.append("# Jelentés\n")
    lines.append(f"Téma: {topic}\n")
    lines.append("Tartalomjegyzék:")
    all_sections = sections_get_all()
    for idx, title, _, _ in all_sections:
        lines.append(f"- {idx+1}. {title}")
    lines.append("")
    for idx, title, body, citations in all_sections:
        lines.append(f"## {title}")
        lines.append(body.rstrip())
        if citations:
            lines.append("Hivatkozások:")
            for c in citations:
                lines.append(f"- {c}")
        lines.append("")
    report = "\n".join(lines)
    b = report.encode("utf-8")
    if len(b) > settings.report_size_limit_bytes:
        target = settings.report_size_limit_bytes
        keep = int(len(b) * 0.95)
        while len(report.encode("utf-8")) > target and keep > 10000:
            report = report[:keep]
            keep = int(keep * 0.95)
    return report

def grok_outline(topic: str, sections: int) -> List[str]:
    if not xai:
        raise HTTPException(status_code=500, detail="XAI_API_KEY missing")
    sysmsg = {"role": "system", "content": "Adj tömör, logikus fejezetcím-tervet egy részletes, 30–50 oldalas jelentéshez. Csak felsorolás, 36 elem."}
    usr = {"role": "user", "content": f"Téma: {topic}\nAdj pontos, informatív fejezetcímeket."}
    resp = xai.chat(settings.model_grok4, [sysmsg, usr], max_tokens=2048, temperature=0.2)
    txt = resp.get("choices", [{}])[0].get("message", {}).get("content", "")
    out = []
    for line in txt.splitlines():
        t = line.strip()
        if not t:
            continue
        if t[0:2].isdigit() and "." in t[:4]:
            t = t.split(".", 1)[1].strip()
        out.append(t)
    if len(out) < sections:
        while len(out) < sections:
            out.append(f"Kiegészítő fejezet {len(out)+1}")
    return out[:sections]

def grok_fast_expand_queries(topic: str, base_queries: List[str], n: int = 10) -> List[str]:
    if not xai:
        return base_queries
    sysmsg = {"role": "system", "content": "Bővíts kulcsszó-kereséseket entitásokkal, szinonímákkal, modellnevekkel, szolgáltatás-változatokkal, régiókkal. Visszatérés pontosan N sorban, soronként egy lekérdezéssel."}
    usr = {"role": "user", "content": f"Téma: {topic}\nAlap kérdések:\n" + "\n".join(base_queries) + f"\nN={n}"}
    resp = xai.chat(settings.model_grok4_fast, [sysmsg, usr], max_tokens=2048, temperature=0.5)
    txt = resp.get("choices", [{}])[0].get("message", {}).get("content", "")
    out = []
    for line in txt.splitlines():
        t = line.strip().strip("-").strip()
        if t:
            out.append(t)
    if len(out) < n:
        while len(out) < n:
            out.append(f"{topic} részletes specifikáció és árak")
    return out[:n]

def exa_collect(query: str, language: Optional[str]) -> List[Dict[str, Any]]:
    if not exa:
        raise HTTPException(status_code=500, detail="EXA_API_KEY missing")
    return exa.search(query, num_results=settings.exa_results_per_query, language=language)

def persist_exa_results(results: List[Dict[str, Any]]) -> int:
    c = 0
    for r in results:
        url = r.get("url") or ""
        title = r.get("title") or url
        snippet = r.get("summary") or r.get("text") or ""
        domain = ""
        try:
            domain = url.split("/")[2]
        except Exception:
            domain = ""
        lang = r.get("language") or ""
        try:
            evidence_add_source(url, title, snippet[:2000], domain, lang)
            c += 1
        except Exception:
            pass
    return c

def glm_analyze_and_claims(topic: str, sid_url_pairs: List[Tuple[str, str]]) -> int:
    if not cerebras:
        raise HTTPException(status_code=500, detail="CEREBRAS_API_KEY missing")
    cnt = 0
    for sid, url in sid_url_pairs:
        messages = [
            {"role": "system", "content": "Kivonatoló és minősítő ügynök vagy. A megadott forrásból emelj ki ellenőrizhető állításokat pontos idézettel. Adj minősítést: strong|medium|weak."},
            {"role": "user", "content": f"Téma: {topic}\nForrás: {url}\nAdj 5–8 rövid állítást JSON tömbként: [{'{'}\"claim\":\"...\",\"quote\":\"...\",\"quality\":\"strong|medium|weak\"{'}'}]."}
        ]
        extra = {"disablereasoning": False}
        resp = cerebras.chat(settings.model_glm46, messages, max_tokens=2000, temperature=settings.temperature_research, extra=extra)
        txt = resp.get("choices", [{}])[0].get("message", {}).get("content", "")
        block = None
        try:
            start = txt.find("[")
            end = txt.rfind("]")
            if start != -1 and end != -1 and end > start:
                block = json.loads(txt[start:end+1])
        except Exception:
            block = None
        if isinstance(block, list):
            for item in block[:12]:
                claim = str(item.get("claim", "")).strip()
                quote = str(item.get("quote", "")).strip()
                quality = str(item.get("quality", "medium")).strip().lower()
                if not claim:
                    continue
                evidence_add_claim(sid, claim[:500], quote[:1000], quality if quality in ("strong", "medium", "weak") else "medium")
                cnt += 1
    return cnt

def author_write_section(topic: str, title: str, k_evidence: List[Tuple[str, str, str]], recent_context: str) -> Tuple[str, List[str]]:
    if not cerebras:
        raise HTTPException(status_code=500, detail="CEREBRAS_API_KEY missing")
    cites = []
    ctx_lines = []
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        for sid, t, url in k_evidence:
            cur.execute("SELECT claim,quote,quality FROM claims WHERE source_id=? LIMIT 3", (sid,))
            claims = cur.fetchall()
            if claims:
                cites.append(url)
                for cl, qt, ql in claims:
                    ctx_lines.append(f"- Forrás: {t} | {url}\nÁllítás: {cl}\nIdézet: {qt}\nMinőség: {ql}")
    ctx = "\n".join(ctx_lines[:60])
    messages = [
        {"role": "system", "content": "Szakmai szerző vagy. Írj koherens, hivatkozott szakaszt magyarul, tárgyilagos hangnemben. Terjedelem ~10 kB. Ne ismételj, minden állítást támassz alá a megadott forráskivonatokkal. Zárj rövid összegzéssel."},
        {"role": "user", "content": f"Téma: {topic}\nSzakasz címe: {title}\nElőzmények kivonata:\n{recent_context}\nForráskivonatok:\n{ctx}\nKimenet: csak a kész szakasz szövege, markdown fejezetcímmel."}
    ]
    extra = {"reasoningeffort": "medium"}
    resp = cerebras.chat(settings.model_gptoss, messages, max_tokens=settings.max_output_tokens, temperature=settings.temperature_author, extra=extra)
    content = resp.get("choices", [{}])[0].get("message", {}).get("content", "")
    return content, cites

def build_recent_context(prev_sections: List[str], limit_chars: int = 4000) -> str:
    out = []
    total = 0
    for s in reversed(prev_sections[-3:]):
        t = s.strip()
        if total + len(t) > limit_chars:
            out.append(t[: max(0, limit_chars - total)])
            break
        out.append(t)
        total += len(t)
    return "\n\n".join(reversed(out))

def orchestrate_job(jid: str, topic: str, hours: float):
    start = time.time()
    deadline = start + hours * 3600.0
    job_update(jid, status="planning", progress=0.02, log_line="Vázlatkészítés indul")
    outline = grok_outline(topic, settings.outline_sections)
    job_update(jid, progress=0.06, log_line=f"Vázlat kész: {len(outline)} fejezet")
    base_queries = [f"{topic} áttekintés", f"{topic} piaci adatok", f"{topic} technikai specifikáció", f"{topic} trendek 2024 2025", f"{topic} árak és összehasonlítás", f"{topic} kockázatok és korlátok"]
    expanded = grok_fast_expand_queries(topic, base_queries, n=18)
    all_queries = base_queries + expanded
    random.shuffle(all_queries)
    job_update(jid, status="research", progress=0.10, log_line=f"Keresés indul {len(all_queries)} lekérdezéssel")
    inserted_sources = 0
    for i, q in enumerate(all_queries):
        if time.time() > deadline:
            break
        results = exa_collect(q, language="hu")
        inserted_sources += persist_exa_results(results)
        p = clamp(0.10 + (i + 1) / max(1, len(all_queries)) * 0.30, 0.10, 0.40)
        job_update(jid, progress=p, log_line=f"Keresés kör {i+1}/{len(all_queries)}: {len(results)} találat")
        if i < settings.search_rounds_soft_limit - 1:
            time.sleep(0.2)
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT id,url FROM sources ORDER BY added_at DESC LIMIT 240")
        sid_url_pairs = cur.fetchall()
    job_update(jid, status="analysis", progress=0.42, log_line=f"Elemzés indul {len(sid_url_pairs)} forráson")
    analyzed_claims = glm_analyze_and_claims(topic, sid_url_pairs)
    job_update(jid, progress=0.55, log_line=f"Elemzés kész, állítások: {analyzed_claims}")
    job_update(jid, status="writing", progress=0.56, log_line="Írás indul")
    prev_texts = []
    for idx, title in enumerate(outline):
        if time.time() > deadline:
            break
        k_evidence = evidence_topk_for_topic(f"{topic} {title}", settings.topk_evidence_per_section)
        recent_ctx = build_recent_context(prev_texts, 5000)
        body, cites = author_write_section(topic, title, k_evidence, recent_ctx)
        section_save(idx, title, body, cites)
        prev_texts.append(body)
        base_p = 0.56
        span = 0.40
        prog = clamp(base_p + (idx + 1) / max(1, len(outline)) * span, base_p, 0.96)
        job_update(jid, progress=prog, log_line=f"Szakasz elkészült: {title}")
    job_update(jid, status="assembling", progress=0.97, log_line="Jelentés összeállítás")
    report_txt = assemble_report(topic)
    report_path = os.path.join(settings.workdir, f"report_{jid}.md")
    with open(report_path, "w", encoding="utf-8") as f:
        f.write(report_txt)
    job_update(jid, status="completed", progress=1.0, report_path=report_path, log_line="Kész")

app = FastAPI()
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

@app.post("/api/run", response_model=JobStatus)
def api_run(req: RunReportRequest, background_tasks: BackgroundTasks):
    if not CEREBRAS_API_KEY or not XAI_API_KEY or not EXA_API_KEY:
        raise HTTPException(status_code=400, detail="Hiányzó API kulcs(ok): CEREBRAS_API_KEY, XAI_API_KEY, EXA_API_KEY")
    jid = job_create(req.topic)
    background_tasks.add_task(orchestrate_job, jid, req.topic, req.hours)
    return job_get(jid)

@app.get("/api/status/{job_id}", response_model=JobStatus)
def api_status(job_id: str):
    return job_get(job_id)

@app.get("/api/report/{job_id}")
def api_report(job_id: str):
    st = job_get(job_id)
    if st.status != "completed" or not st.report_path or not os.path.exists(st.report_path):
        raise HTTPException(status_code=404, detail="Jelentés nem kész")
    def gen():
        with open(st.report_path, "rb") as f:
            while True:
                chunk = f.read(65536)
                if not chunk:
                    break
                yield chunk
    return StreamingResponse(gen(), media_type="text/markdown")

@app.post("/api/search")
def api_search(req: SearchRequest):
    if not EXA_API_KEY:
        raise HTTPException(status_code=400, detail="Hiányzó EXA_API_KEY")
    out = {"mode": "websets" if req.websets else "search", "results": []}
    if req.websets:
        ws = exa.webset_create(req.query, req.count)
        wid = ws.get("id") or ws.get("webset", {}).get("id") or ""
        if not wid:
            raise HTTPException(status_code=502, detail="Webset ID hiányzik")
        sr = exa.webset_search(wid, req.query, req.count)
        out["webset_id"] = wid
        out["results"] = sr
        return JSONResponse(out)
    res = exa.search(req.query, num_results=req.count, language=req.language)
    out["results"] = res
    return JSONResponse(out)

@app.get("/healthz")
def healthz():
    return {"ok": True, "time": now_utc()}

