<script>
const sel=(x)=>document.querySelector(x)
const api=(p,opts={})=>fetch(p,opts).then(async r=>{if(!r.ok){let t=await r.text();throw new Error(t)}return r.headers.get("content-type")&&r.headers.get("content-type").includes("application/json")?r.json():r.text()})
const logEl=sel("#log")
function appendLog(s){const now=new Date().toISOString();logEl.textContent+=`[${now}] ${s}\n`;logEl.scrollTop=logEl.scrollHeight}
async function startRun(){
  const topic=sel("#topic").value.trim()
  const hours=parseFloat(sel("#hours").value)
  if(!topic||!(hours>0)){appendLog("Hiányzó téma vagy hibás időkeret");return}
  sel("#startBtn").disabled=true
  try{
    const res=await api("/api/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({topic,hours})})
    sel("#jobId").textContent=res.id
    sel("#status").textContent=res.status
    sel("#progress").textContent=(Math.round(res.progress*1000)/10)+"%"
    appendLog("Feladat indítva: "+res.id)
    poll(res.id)
  }catch(e){appendLog("Hiba: "+e.message)}finally{sel("#startBtn").disabled=false}
}
async function poll(id){
  for(;;){
    await new Promise(r=>setTimeout(r,2500))
    try{
      const st=await api("/api/status/"+encodeURIComponent(id))
      sel("#status").textContent=st.status
      sel("#progress").textContent=(Math.round(st.progress*1000)/10)+"%"
      sel("#watchId").value=id
      sel("#watchStatus").textContent=st.status
      sel("#watchProgress").textContent=(Math.round(st.progress*1000)/10)+"%"
      logEl.textContent=st.logs.join("\n")
      logEl.scrollTop=logEl.scrollHeight
      if(st.status==="completed"&&st.report_path){
        const a=sel("#dl")
        a.style.display="inline-block"
        a.href="/api/report/"+encodeURIComponent(id)
        a.textContent="Jelentés letöltése"
        appendLog("Kész: jelentés elérhető")
        break
      }
      if(st.status==="failed"||st.status==="canceled"){appendLog("Leállt");break}
    }catch(e){appendLog("Állapot hiba: "+e.message);break}
  }
}
async function doSearch(){
  const q=sel("#q").value.trim()
  const count=parseInt(sel("#count").value)
  const language=sel("#lang").value.trim()||null
  const mode=sel("#mode").value
  if(!q){appendLog("Üres lekérdezés");return}
  sel("#searchBtn").disabled=true
