    sel("#searchInfo").textContent=(Array.isArray(res.results)?res.results.length:0)+" találat"
    const tbody=sel("#results")
    if(Array.isArray(res.results)){
      for(const r of res.results){
        const tr=document.createElement("tr")
        const title=r.title||r.url||""
        const url=r.url||""
        const snippet=r.summary||r.text||r.snippet||""
        const td1=document.createElement("td")
        td1.textContent=title
        const td2=document.createElement("td")
        const a=document.createElement("a");a.href=url;a.target="_blank";a.textContent=url;td2.appendChild(a)
        const td3=document.createElement("td")
        td3.textContent=(snippet||"").slice(0,280)
        tr.appendChild(td1);tr.appendChild(td2);tr.appendChild(td3)
        tbody.appendChild(tr)
      }
    }else{
      const tr=document.createElement("tr")
      const td=document.createElement("td");td.colSpan=3;td.textContent="Strukturált Webset válasz érkezett."
      tr.appendChild(td);sel("#results").appendChild(tr)
    }
  }catch(e){appendLog("Keresés hiba: "+e.message)}finally{sel("#searchBtn").disabled=false}
}
async function watch(){
  const id=sel("#watchId").value.trim()
