      a.href="/api/report/"+encodeURIComponent(id)
      a.textContent="Jelentés letöltése"
    }
  }catch(e){appendLog("Watch hiba: "+e.message)}
}
sel("#startBtn").addEventListener("click",startRun)
sel("#searchBtn").addEventListener("click",doSearch)
sel("#watchBtn").addEventListener("click",watch)
